export interface HubSpotDealWebhookPayload {
  dealId: string
  objectId: string
  properties: {
    dealname: string
    website: string
    hubspot_owner_id: string
  }
  subscriptionId: string
  propertyName: string
  propertyValue: string
  eventId: string
  occurredAt: number
}

export interface ConnectorConfig {
  salesforceInstance: string
  salesforceAccessToken: string
  fetch?: typeof fetch
}

export interface ConnectorResult {
  salesforceAccountId: string
  created: boolean
  success: boolean
}

function validatePayload(payload: unknown): HubSpotDealWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.dealId && !p.objectId) {
    throw new Error('Missing required field: dealId or objectId')
  }
  if (!p.properties || typeof p.properties !== 'object') {
    throw new Error('Missing required field: properties')
  }
  const props = p.properties as Record<string, unknown>
  if (!props.website || typeof props.website !== 'string') {
    throw new Error('Missing required field: properties.website')
  }
  if (!props.dealname || typeof props.dealname !== 'string') {
    throw new Error('Missing required field: properties.dealname')
  }
  if (!props.hubspot_owner_id || typeof props.hubspot_owner_id !== 'string') {
    throw new Error('Missing required field: properties.hubspot_owner_id')
  }
  return payload as HubSpotDealWebhookPayload
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  const validated = validatePayload(payload)
  const fetchFn = config.fetch ?? fetch

  const dealId = validated.dealId || validated.objectId
  const { website, dealname, hubspot_owner_id } = validated.properties

  const url = `https://${config.salesforceInstance}.salesforce.com/services/data/v68.0/sobjects/Account/External_Id__c/${encodeURIComponent(dealId)}`

  const body = {
    Name: dealname,
    Website: website,
    OwnerId: hubspot_owner_id,
    External_Id__c: dealId,
  }

  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.salesforceAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (response.status === 300) {
    const errorBody = await response.json().catch(() => ({}))
    throw new Error(`Salesforce upsert returned 300 Multiple Choices for ${url}: ${JSON.stringify(errorBody)}`)
  }
  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Salesforce upsert failed with ${response.status} ${response.statusText} for ${url}: ${errorText}`)
  }

  const result = (await response.json()) as { id: string; success: boolean; errors: unknown[]; created: boolean }

  if (!result.success) {
    throw new Error(`Salesforce upsert reported failure for ${url}: ${JSON.stringify(result.errors)}`)
  }

  return {
    salesforceAccountId: result.id,
    created: result.created,
    success: result.success,
  }
}

